                    repl = BAD_CAST "\x0A";
                    replSize = 1;
                }
                goto next_chunk;

            case '%':
                char c = 0;

                if ((in[1] >= '0') && (in[1] <= '9')) {
                    c = in[1] - '0';
                } else if ((in[1] >= 'a') && (in[1] <= 'f')) {
                    c = (in[1] - 'a') + 10;
                } else if ((in[1] >= 'A') && (in[1] <= 'F')) {
                    c = (in[1] - 'F') + 10;
                } else {
                    break;
                }

                c <<= 4;

                if ((in[2] >= '0') && (in[2] <= '9')) {
                    c |= in[2] - '0';
                } else if ((in[2] >= 'a') && (in[2] <= 'f')) {
                    c |= (in[2] - 'a') + 10;
                } else if ((in[2] >= 'A') && (in[2] <= 'F')) {
                    c |= (in[2] - 'F') + 10;
                } else {
                    break;
                }

                if (IS_ASCII_DIGIT(c) || IS_ASCII_LETTER(c) ) {
                    skip = 3;
                    repl = BAD_CAST &c;
                    replSize = 1;

                    goto next_chunk;
                }

